import React, { useState } from 'react';
import { updateCart, removeFromCart } from '../../api/axiosConfig';
import './CartItem.css';


const CartItem = ({ item, onCartUpdate }) => {
    const [nights, setNumbers] = useState(item.numbers || 1);
    const [people, setCover] = useState(item.cover || "Тверда");

    const handleNumbersChange = async (e) => {
        const updatedNumbers = Number(e.target.value);
        setNumbers(updatedNumbers);
        await updateCart(item.id, { nights: updatedNumbers, people });
        onCartUpdate(); 
    };

    const handleCoverChange = async (e) => {
        const updatedCover = e.target.value;
        setCover(updatedCover);
        await updateCart(item.id, { nights, people: updatedCover });
        onCartUpdate(); 
    };

    const handleRemove = async () => {
        await removeFromCart(item.id);
        onCartUpdate(); 
    };

