//     const [cover, setCover] = useState(item.cover || "Тверда"); // Зберігаємо обкладинку як текст

//     // Обробка зміни кількості книг
//     const handleNumbersChange = async (e) => {
//         const updatedNumbers = Number(e.target.value);
//         setNumbers(updatedNumbers);
//         try {
//             await updateCart(item.id, { numbers: updatedNumbers, cover });
//             onCartUpdate();  // Оновлення кошика після зміни
//         } catch (error) {
//             console.error("Помилка оновлення кошика:", error);
//         }
//     };

//     // Обробка зміни типу обкладинки
//     const handleCoverChange = async (e) => {
//         const updatedCover = e.target.value;  // Оновлення типу обкладинки
//         setCover(updatedCover);
//         try {
//             await updateCart(item.id, { numbers, cover: updatedCover });
//             onCartUpdate();  // Оновлення кошика після зміни
//         } catch (error) {
//             console.error("Помилка оновлення обкладинки:", error);
//         }
//     };

//     // Обробка видалення товару з кошика
//     const handleRemove = async () => {
//         try {
//             await removeFromCart(item.id);
//             onCartUpdate();  // Оновлення кошика після видалення
//         } catch (error) {
//             console.error("Помилка видалення товару з кошика:", error);
//         }
//     };

    // Максимальні значення для вибору кількості і обкладинки
    const maxNumbers = item.maxNumbers || 10;
    const maxCover = item.maxCover || 3;

    // Розрахунок загальної вартості, з урахуванням обкладинки
    const priceMultiplier = cover === "Тверда" ? 1 : cover === "М'яка" ? 0.9 : 1.1;
    const totalPrice = item.price * numbers * priceMultiplier;

    const BACKEND_URL = "http://localhost:5000/static/media";
    const imagePath = `${BACKEND_URL}/${item.image}`;

    return (
        <div className="cart-item">
            <div className="item-image">
                <img src={imagePath} alt={item.title} />
            </div>
            <div className="item-details">
                <h3>{item.title}</h3>
                <p className="item-price">Ціна: {item.price} грн</p>

                <label>
                    Кількість книг:
                    <select value={numbers} onChange={handleNumbersChange}>
                        {Array.from({ length: maxNumbers }, (_, index) => (
                            <option key={index + 1} value={index + 1}>{index + 1}</option>
                        ))}
                    </select>
                </label>

                <label>
                    Обкладинка:
                    <select value={cover} onChange={handleCoverChange}>
                        <option value="Тверда">Тверда</option>
                        <option value="М'яка">М'яка</option>
                        <option value="Суперобкладинка">Суперобкладинка</option>
                    </select>
                </label>
            </div>
            <div className="item-total">
                Загальна вартість: {totalPrice} грн
            </div>

            <button className="remove-button" onClick={handleRemove}>Видалити</button>
        </div>
    );
};

export default CartItem;
